// Differential checks of CallChain-faithful.js against Lean, generated by leanscript --check
import * as M from "./CallChain-faithful.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  // a list of cons cells (`ListRepr.taggedUnion`) is shown as its elements
  if (v !== null && typeof v === "object" && (v.tag === 0 || v.tag === 1)) {
    const a = [];
    for (; v.tag === 1; v = v._2) a.push(v._1);
    return show(a);
  }
  // a record (a structure-like type) is shown as its fields: `{a, b}`
  if (v !== null && typeof v === "object" && !("tag" in v) && "_1" in v) {
    const fs = [];
    for (let i = 1; ("_" + i) in v; i++) fs.push(show(v["_" + i]));
    return "{" + fs.join(", ") + "}";
  }
  return String(v);
}
// a union `{ tag: i, _1: …, … }` of leaf fields is shown as `i(…, …)`
function showUnion(v) {
  const fs = [];
  for (let i = 1; ("_" + i) in v; i++) fs.push(show(v["_" + i]));
  return v.tag + "(" + fs.join(", ") + ")";
}
// a recursive union: as `showUnion`, the fields marked in `rec[tag]` (the type itself) printed
// the same way, one level less deep (`…` at depth 0, as `showExpr` cuts it in Lean)
function showTree(v, rec, d) {
  if (d === 0) return "…";
  if (typeof v === "number") return v + "()";
  const r = rec[v.tag] || [];
  const fs = [];
  for (let i = 1; ("_" + i) in v; i++)
    fs.push(r[i - 1] ? showTree(v["_" + i], rec, d - 1) : show(v["_" + i]));
  return v.tag + "(" + fs.join(", ") + ")";
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("chain6((x, y) => ((v) => (v > 0n ? v : 0n))(x * 10n + y))", () => M.chain6((x, y) => ((v) => (v > 0n ? v : 0n))(x * 10n + y)), "#[12, 34, 56, 78, 100, 122]", false);
check("chain6((x, y) => ((v) => (v > 0n ? v : 0n))(y * 3n - x))", () => M.chain6((x, y) => ((v) => (v > 0n ? v : 0n))(y * 3n - x)), "#[5, 9, 13, 17, 21, 25]", false);
check("chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(x * 10n + y), 0n, 0n)", () => M.chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(x * 10n + y), 0n, 0n), "#[0, 0, 0, 0, 10, 122, 0, 0]", false);
check("chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(x * 10n + y), 1n, 1n)", () => M.chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(x * 10n + y), 1n, 1n), "#[11, 11, 11, 11, 21, 122, 10, 1]", false);
check("chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(y * 3n - x), 1n, 0n)", () => M.chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(y * 3n - x), 1n, 0n), "#[0, 3, 2, 0, 0, 25, 0, 3]", false);
check("chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(x * 10n + y), 0n, 5n)", () => M.chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(x * 10n + y), 0n, 5n), "#[5, 50, 0, 55, 15, 122, 50, 0]", false);
check("chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(x * 10n + y), 5n, 0n)", () => M.chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(x * 10n + y), 5n, 0n), "#[50, 5, 55, 0, 60, 122, 0, 5]", false);
check("chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(y * 3n - x), 0n, 2n)", () => M.chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(y * 3n - x), 0n, 2n), "#[6, 0, 0, 4, 5, 25, 0, 0]", false);
check("chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(x * 10n + y), 2n, 2n)", () => M.chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(x * 10n + y), 2n, 2n), "#[22, 22, 22, 22, 32, 122, 20, 2]", false);
check("chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(y * 3n - x), 2n, 1n)", () => M.chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(y * 3n - x), 2n, 1n), "#[1, 5, 4, 2, 0, 25, 0, 6]", false);
check("chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(x * 10n + y), 1n, 13n)", () => M.chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(x * 10n + y), 1n, 13n), "#[23, 131, 11, 143, 33, 122, 130, 1]", false);
check("chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(x * 10n + y), 13n, 1n)", () => M.chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(x * 10n + y), 13n, 1n), "#[131, 23, 143, 11, 141, 122, 10, 13]", false);
check("chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(y * 3n - x), 1n, 5n)", () => M.chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(y * 3n - x), 1n, 5n), "#[14, 0, 2, 10, 13, 25, 0, 3]", false);
check("chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(y * 3n - x), 13n, 0n)", () => M.chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(y * 3n - x), 13n, 0n), "#[0, 39, 26, 0, 0, 25, 0, 39]", false);
check("chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(x * 10n + y), 5n, 5n)", () => M.chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(x * 10n + y), 5n, 5n), "#[55, 55, 55, 55, 65, 122, 50, 5]", false);
check("chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(y * 3n - x), 5n, 2n)", () => M.chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(y * 3n - x), 5n, 2n), "#[1, 13, 10, 4, 0, 25, 0, 15]", false);
check("chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(y * 3n - x), 2n, 13n)", () => M.chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(y * 3n - x), 2n, 13n), "#[37, 0, 4, 26, 36, 25, 0, 6]", false);
check("chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(x * 10n + y), 13n, 13n)", () => M.chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(x * 10n + y), 13n, 13n), "#[143, 143, 143, 143, 153, 122, 130, 13]", false);
check("chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(y * 3n - x), 13n, 5n)", () => M.chainVars((x, y) => ((v) => (v > 0n ? v : 0n))(y * 3n - x), 13n, 5n), "#[2, 34, 26, 10, 1, 25, 0, 39]", false);
check("swapped((x, y) => ((v) => (v > 0n ? v : 0n))(x * 10n + y))", () => M.swapped((x, y) => ((v) => (v > 0n ? v : 0n))(x * 10n + y)), "#[56, 34, 12]", false);
check("swapped((x, y) => ((v) => (v > 0n ? v : 0n))(y * 3n - x))", () => M.swapped((x, y) => ((v) => (v > 0n ? v : 0n))(y * 3n - x)), "#[13, 9, 5]", false);

console.log(`CallChain-faithful.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
